import React, { useEffect, useState } from 'react'
import * as Yup from "yup";
import { useStateContext } from '../../../../contexts/ContextProvider'
import { useFormik } from "formik";
import { CustomForm, CustomFormItem, CustomInput, CustomTextArea } from '../../../../components'
import useApi from '../../../../hooks/useApi';
import hospitalsApi from '../../../../api/hospitals/hospitalsApi';
import { toast, ToastContainer } from 'react-toastify';

export default function DischargeSummaryForm({ selectedAdmission, dischargeSummary, setdischargeSummary,updated,setupdated }) {

  const { currentColor,loggedInUser } = useStateContext()


    const [errors, setErrors] = useState([])
      useEffect(() => {
        if (errors && errors.length) {
          errors.map((x) => {
            toast.error(x);
          });
        }
      }, [errors]);

  const createDischargeSummaryApi = useApi(hospitalsApi.hospitalInpatientAction)
  const createDischargeSummary = async (data) => {
    setupdated(false)
    await createDischargeSummaryApi.request(data)
  }


  useEffect(() => {

    if (createDischargeSummaryApi.data) {

      if (createDischargeSummaryApi.data.discharge_summary) {
        toast.success(createDischargeSummaryApi.data.response_message)
        setdischargeSummary(createDischargeSummaryApi.data.discharge_summary)
        setupdated(true)
      }


      if (createDischargeSummaryApi.data.errors) {
    
        setErrors(createDischargeSummaryApi.data.errors)
      }
    }
    console.log("createDischargeSummaryApi.data", createDischargeSummaryApi.data)
  }, [createDischargeSummaryApi.data])
  const formik = useFormik({
    initialValues: {
      admission_diagnosis: "",
      final_diagnosis: "",
      other_illness: "",
      clinical_summary: "",
      investigations: "",
      treatment: "",
      recommendation: "",

    },

    validationSchema: Yup.object({
      admission_diagnosis: Yup.string().required().label("Admission diagnosis"),
      final_diagnosis: Yup.string().required().label("Final diagnosis"),
      clinical_summary: Yup.string().required().label("Clinical summary"),
      investigations: Yup.string().required().label("Investigations"),
      treatment: Yup.string().required().label("Treatment"),
      recommendations: Yup.string().required().label("Discharge recommendations"),

    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      const data = {
        "action": "CreateDischargeSummary",
        "admission": selectedAdmission.id,
        "admission_diagnosis": values.admission_diagnosis,
        "final_diagnosis": values.final_diagnosis,
        "other_illness": values.other_illness,
        "clinical_summary": values.clinical_summary,
        "treatment": values.treatment,
        "investigations": values.investigations,
        "operations": values.operations,
        "recommendations": values.recommendations


      }

      createDischargeSummary(data)

    },
  });


  return (
    <div className='w-full'><CustomForm
      layout="horizontal"
      handleFinish={formik.handleSubmit}
      className=" justify-center items-center w-full px-2 "
    >
      <ToastContainer theme='colored' position='bottom-center' />
      <div className='grid grid-cols-1 md:grid-cols-2 gap-2'>
        <CustomFormItem
          touched={formik.touched.admission_diagnosis}
          error={formik.errors.admission_diagnosis}
        >

          <CustomTextArea
            className="text-start"
            id="admission_diagnosis"
            name="admission_diagnosis"
            onChange={formik.handleChange}
            placeholder="Admission diagnosis"
            label="Admission diagnosis"
            size="large"
            type="text"
            value={formik.values.admission_diagnosis}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.final_diagnosis}
          error={formik.errors.final_diagnosis}
        >

          <CustomTextArea
            className="text-start"
            id="final_diagnosis"
            name="final_diagnosis"
            onChange={formik.handleChange}
            placeholder="Final diagnosis"
            label="Final diagnosis"
            size="large"
            type="text"
            value={formik.values.final_diagnosis}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.other_illness}
          error={formik.errors.other_illness}
        >

          <CustomTextArea
            className="text-start"
            id="other_illness"
            name="other_illness"
            onChange={formik.handleChange}
            placeholder="Other illness"
            label="Other illness"
            size="large"
            type="text"
            value={formik.values.other_illness}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.clinical_summary}
          error={formik.errors.clinical_summary}
        >
          <CustomTextArea
            className="text-start"
            id="clinical_summary"
            name="clinical_summary"
            onChange={formik.handleChange}
            placeholder="Clinical summary"
            label="Clinical summary"
            size="large"
            type="text"
            value={formik.values.clinical_summary}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.investigations}
          error={formik.errors.investigations}
        >
          <CustomTextArea
            className="text-start"
            id="investigations"
            name="investigations"
            onChange={formik.handleChange}
            placeholder="Investigations done"
            label="Investigations done"
            size="large"
            type="text"
            value={formik.values.investigations}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.treatment}
          error={formik.errors.treatment}
        >
          <CustomTextArea
            className="text-start"
            id="treatment"
            name="treatment"
            onChange={formik.handleChange}
            placeholder="Treatment given"
            label="Treatment given"
            size="large"
            type="text"
            value={formik.values.treatment}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.operations}
          error={formik.errors.operations}
        >
          <CustomTextArea
            className="text-start"
            id="operations"
            name="operations"
            onChange={formik.handleChange}
            placeholder="Operations done"
            label="Operations done"
            size="large"
            type="text"
            value={formik.values.operations}
          />
        </CustomFormItem>
        <CustomFormItem
          touched={formik.touched.recommendations}
          error={formik.errors.recommendations}
        >
          <CustomTextArea
            className="text-start"
            id="recommendations"
            name="recommendations"
            onChange={formik.handleChange}
            placeholder="Discharge recommendationss"
            label="Discharge recommendationss"
            size="large"
            type="text"
            value={formik.values.recommendations}
          />
        </CustomFormItem>



      </div>
      <button
        id="formikPrescription"
        style={{ background: currentColor }}
        className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
        color="primary"
        type="submit"
      >
        Submit
      </button>
    </CustomForm></div>
  )
}
