import { Accordion, AccordionItem } from '@heroui/react'
import React from 'react'

export default function DischargeSummaryDetails({ dischargeSummary }) {
  return (
    <div className='w-full'>


      <Accordion variant='splitted' className='w-full' isCompact>
        <AccordionItem key="1" aria-label="Admission Diagnosis" title={
          <p className='font-bold'>Admission Diagnosis</p>
        }>
          {dischargeSummary.admission_diagnosis}
        </AccordionItem>
        <AccordionItem key="2" aria-label="Final Diagnosis" title={
          <p className='font-bold'>Final Diagnosis</p>
        }>
          {dischargeSummary.final_diagnosis}
        </AccordionItem>
        <AccordionItem key="3" aria-label="Other illness" title={
          <p className='font-bold'>Other illness</p>
        }>
          {dischargeSummary.other_illness}
        </AccordionItem>

        <AccordionItem key="4" aria-label="Clinical Summary" title={
          <p className='font-bold'>Clinical Summary</p>
        } >
          {dischargeSummary.clinical_summary}
        </AccordionItem>

        <AccordionItem key="5" aria-label="Operations done" title={
          <p className='font-bold'>Operations done</p>
        } >
          {dischargeSummary.operations}
        </AccordionItem>
        <AccordionItem key="6" aria-label="Investigations" title={
          <p className='font-bold'>Investigations</p>
        } >
          {dischargeSummary.investigations}
        </AccordionItem>
        <AccordionItem key="7" aria-label="Treatment" title={
          <p className='font-bold'>Treatment</p>
        } >
          {dischargeSummary.treatment}
        </AccordionItem>

        <AccordionItem key="8" aria-label="Recommendations" title={
          <p className='font-bold'>Recommendations</p>
        }>
          {dischargeSummary.recommendations}
        </AccordionItem>

    
      </Accordion>
    </div>
  )
}
