import React, { useEffect, useState } from 'react'
import DischargeSummaryForm from './DischargeSummaryForm'
import DischargeSummaryDetails from './DischargeSummaryDetails'
import { toast } from 'react-toastify'
import useApi from '../../../../hooks/useApi'
import { useLocation } from 'react-router-dom'
import { useStateContext } from '../../../../contexts/ContextProvider'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import PrescriptionsPage from '../../visitors/PrescriptionsPage'
import dependantsApi from '../../../../api/dependantsApi'

export default function DischargeSummary() {
    const {loggedInUser} = useStateContext()

    const [selectedAdmission, setselectedAdmission] = useState()
    const [selectedDependant, setselectedDependant] = useState()
    const [dischargeSummary, setdischargeSummary] = useState()
    const [errors, setErrors] = useState([])
    const [showForm, setshowForm] = useState(dischargeSummary ? false : true)

    const [updated, setupdated] = useState(false)
    const location = useLocation()
    const [selectedDependantId, setselectedDependantId] = useState()
    useEffect(() => {
        setselectedDependantId(location.state.dependant)
    }, [location])






    //Get admission

    const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
    const getDependantAdmission = async (id) => {
        await getAdmissionApi.request({
            "action": "GetDependantAdmission",
            "dependant": id
        })
    }

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);
    useEffect(() => {
        if (getAdmissionApi.data) {

            if (getAdmissionApi.data.admission) {
                setselectedAdmission(getAdmissionApi.data.admission)
            }
        }

        console.log("getAdmissionApi.data", getAdmissionApi.data)
    }, [getAdmissionApi.data])


    const getDependantDetailsApi = useApi(dependantsApi.dependantsAction)
    const getDependantDetails = async (id) => {
        await getDependantDetailsApi.request({
            "action": "GetDependantDetails",
            "dependant_id": id
        })
    }


    useEffect(()=>{
        if(getDependantDetailsApi.data){
            if(getDependantDetailsApi.data.dependant){
                setselectedDependant(getDependantDetailsApi.data.dependant)
            }
        }
        console.log("getDependantDetailsApi.data",getDependantDetailsApi.data)
    },[getDependantDetailsApi.data])


    useEffect(() => {
        if (selectedDependantId) {
            getDependantAdmission(selectedDependantId)
            getDependantDetails(selectedDependantId);
            console.log("selectedDependantId",selectedDependantId)
        }

    }, [selectedDependantId])


    //Get discharge summary

    const getdischargeSummaryApi = useApi(hospitalsApi.hospitalInpatientAction)
    const getdischargeSummary = async () => {
        await getdischargeSummaryApi.request({
            "action": "GetAdmissionDischargeSummary",
            "admission": selectedAdmission.id

        })
    }

    useEffect(() => {
        if (getdischargeSummaryApi.data) {
            if (getdischargeSummaryApi.data.discharge_summary) {
                setdischargeSummary(getdischargeSummaryApi.data.discharge_summary)
                setshowForm(false)
            }
        }
        console.log("getdischargeSummaryApi.data", getdischargeSummaryApi.data)
    }, [getdischargeSummaryApi.data])

    useEffect(() => {

        if (selectedAdmission) {
            getdischargeSummary();
        }

    }, [selectedAdmission])

    return (
        <div>
            <p className='text-xl font-semibold text-center'>Discharge Summary</p>
            {showForm ? <DischargeSummaryForm selectedAdmission={selectedAdmission} dischargeSummary={dischargeSummary} setdischargeSummary={setdischargeSummary} updated={updated} setupdated={setupdated}/> : <div></div>}

            {selectedDependant ? <PrescriptionsPage selectedDependant={selectedDependant} selectedAdmission={selectedAdmission} nature="DISCHARGE" originDepartment={loggedInUser.employment_department} /> : <div></div>}
            {dischargeSummary ? <DischargeSummaryDetails dischargeSummary={dischargeSummary} /> : <div></div>}

        </div>
    )
}
